using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;
using UnityEngine.AI;

namespace Starfall {
 public sealed class FrontierVerification:MonoBehaviour {
  readonly List<string> report=new List<string>();CampaignRuntime c;SceneDirector director;int failures,baseline;string output;
  void Check(string title,bool good){report.Add((good?"PASS ":"FAIL ")+title);Debug.Log("FRONTIER_QA "+report[report.Count-1]);if(!good)failures++;}
  IEnumerator Wait(Func<bool> predicate,float seconds=20){float end=Time.realtimeSinceStartup+seconds;while(!predicate()&&Time.realtimeSinceStartup<end)yield return null;Check("Transition/timer completed",predicate());}
  IEnumerator Start(){if(!Array.Exists(Environment.GetCommandLineArgs(),a=>a=="-frontierQA"))yield break;yield return new WaitForSeconds(2);c=CampaignRuntime.Current;director=GetComponent<SceneDirector>();output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../QA/Reports/Frontier"));Directory.CreateDirectory(output);baseline=FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;
   try{yield return Run();}finally{File.WriteAllLines(Path.Combine(output,"frontier-report.txt"),report);Debug.Log(failures==0?"FRONTIER_QA_PASS":"FRONTIER_QA_FAIL "+failures);Application.Quit(failures==0?0:2);}
  }
  void Warp(Vector3 point){var p=c.Explorer;p.Motor.enabled=false;p.transform.position=point;p.Motor.enabled=true;p.ResetMotion();Physics.SyncTransforms();}
  void Freeze(){foreach(var a in c.Explorer.arena.creatures){a.enabled=false;if(a.Agent&&a.Agent.isOnNavMesh){a.Agent.ResetPath();a.Agent.isStopped=true;}var elite=a.GetComponent<EliteCreature>();if(elite)elite.enabled=false;}var titan=FindFirstObjectByType<TitanAreaAttack>();if(titan){titan.Cancel();titan.AttackEnabled=false;}if(c.RegionView.boss)c.RegionView.boss.enabled=false;}
  bool Approach(string key){var region=c.RegionView;var site=region.FrontierSitePosition(key);for(int i=0;i<8;i++){var p=site+new Vector3(Mathf.Cos(i*Mathf.PI/4)*2,0,Mathf.Sin(i*Mathf.PI/4)*2);if(!NavMesh.SamplePosition(p,out var hit,1.8f,NavMesh.AllAreas))continue;Warp(hit.position);if(region.Near(key))return true;}return false;}
  IEnumerator Shot(string name,Camera camera){yield return new WaitForEndOfFrame();var target=RenderTexture.GetTemporary(1600,900,24);var old=camera.targetTexture;var active=RenderTexture.active;Texture2D texture=null;try{camera.targetTexture=target;camera.Render();RenderTexture.active=target;texture=new Texture2D(1600,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,900),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),texture.EncodeToPNG());Check("Rendered "+name,true);}finally{camera.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(target);if(texture)Destroy(texture);}}
  IEnumerator WalkTo(Vector3 goal,string label){var p=c.Explorer;var path=new NavMeshPath();bool found=NavMesh.SamplePosition(goal,out var hit,3,NavMesh.AllAreas)&&NavMesh.CalculatePath(p.transform.position,hit.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;Check("Navigation path "+label,found);if(!found)yield break;int steps=0;for(int i=0;i<path.corners.Length;i++){var corner=path.corners[i];float stop=i==path.corners.Length-1&&Vector3.Distance(goal,p.returnBeacon.position)<.1f?2.5f:.65f;while(CreatureArena.FlatDistance(p.transform.position,corner)>stop&&steps++<2400){var direction=corner-p.transform.position;direction.y=0;direction.Normalize();p.Drive(new Vector2(Vector3.Dot(direction,p.transform.right),Vector3.Dot(direction,p.transform.forward)),false,false,1/60f);Physics.SyncTransforms();yield return null;}}Check("Collision motor walks "+label,Vector3.Distance(p.transform.position,hit.position)<3);report.Add("ROUTE "+label+" steps="+steps+" end="+p.transform.position+" goal="+hit.position);}
  int Total(ItemId item){int n=c.State.bag.Count(item)+c.State.warehouse.Count(item);foreach(var box in c.State.crates)n+=box.items.Count(item);return n;}
  IEnumerator Leave(){c.Explorer.Return();yield return Wait(()=>!director.battle.IsEngaged);yield return null;Check("Scene return releases expansion objects",Math.Abs(FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length-baseline)<8);}
  IEnumerator Survey(int area){var r=c.RegionView;Check("Survey target reachable "+area,Approach("survey"));if(!r.Near("survey"))yield break;c.Explorer.viewCamera.transform.LookAt(r.FrontierSitePosition("survey")+Vector3.up);yield return Shot("survey-"+area,c.Explorer.viewCamera);
   if(area==1){for(int i=0;i<5;i++)r.AdvanceSurvey(true,.25f);float progress=r.SurveyProgress;c.Explorer.SetPaused(true);Check("Paused hold does not advance",!r.AdvanceSurvey(true,.25f)&&Mathf.Abs(r.SurveyProgress-progress)<.01f);c.Explorer.SetPaused(false);r.AdvanceSurvey(false,.1f);Check("Released hold resets progress",r.SurveyProgress==0);for(int i=0;i<4;i++)r.AdvanceSurvey(true,.25f);Warp(c.Explorer.transform.position+Vector3.right*.9f);r.AdvanceSurvey(true,.1f);Check("Movement interrupts survey",r.SurveyProgress==0);Approach("survey");}
   for(int i=0;i<13;i++)r.AdvanceSurvey(true,.25f);Check("Survey completes once "+area,c.Exp("survey-"+area));int count=c.FrontierCount("survey");Check("Completed survey cannot repeat "+area,!c.CompleteSurvey(area)&&c.FrontierCount("survey")==count);
  }
  IEnumerator Ruin(int area){var r=c.RegionView;var config=FrontierCatalog.Current.RuinFor(area);Check("Unsolved ruin cannot claim directly",!c.CompleteRuin(area));if(area==3){yield return Wait(()=>!r.MemoryPlaying,8);Check("Memory clue visibly previews before input",!r.MemoryPlaying);Check("First memory crystal reachable",Approach("ruin-control-0"));Check("Wrong sequence restarts without reward",Approach("ruin-control-1")&&!r.PressRuin(1)&&r.MemoryPlaying&&!c.RuinFor(area).solved);yield return Wait(()=>!r.MemoryPlaying,8);
    for(int i=0;i<config.solution.Length;i++){int key=config.solution[i];Check("Memory crystal interaction "+i,Approach("ruin-control-"+key)&&r.PressRuin(key));}
   }else{for(int i=0;i<3;i++){Check("Physical ruin control reachable "+area+" / "+i,Approach("ruin-control-"+i));for(int step=0;step<config.solution[i];step++)Check("Adjust physical control "+area+" / "+i+" / "+step,r.PressRuin(i));}}
   Check("Ruin solved and reward committed "+area,c.RuinFor(area).solved&&c.Exp("ruin-"+area));int parts=Total(ItemId.MachineParts);Check("Solved ruin reward cannot repeat "+area,!c.CompleteRuin(area)&&Total(ItemId.MachineParts)==parts);c.Explorer.viewCamera.transform.LookAt(r.FrontierSitePosition("ruin-control-1")+Vector3.up);yield return Shot("ruin-"+area,c.Explorer.viewCamera);
  }
  IEnumerator Variant(bool frost){var p=c.Explorer;FrontierCreatureTrait variant=null;foreach(var a in p.arena.creatures)if(a.GetComponent<FrontierCreatureTrait>())variant=a.GetComponent<FrontierCreatureTrait>();Check("Unique sparse variant exists",variant&&variant.frost==frost);if(!variant)yield break;var actor=variant.GetComponent<AlienCreature>();Check("Variant stable identity and health",actor.GetComponent<CreatureVitality>().persistentId.StartsWith("frontier-")&&actor.GetComponent<CreatureVitality>().maxHealth==(frost?190:240));
   Warp(actor.Home+Vector3.left*9);yield return null;foreach(var other in p.arena.creatures)if(other!=actor)Check("Variant home remains dispersed",CreatureArena.FlatDistance(actor.Home,other.Home)>=12);Check("Variant spawn outside safe beacon",CreatureArena.FlatDistance(actor.Home,p.returnBeacon.position)>15);p.viewCamera.transform.LookAt(actor.visual.position+Vector3.up);yield return Shot(frost?"frost-wing":"magnetic-ground",p.viewCamera);
   Check("Committed special ignores sound lure",!actor.IsWindingUp);var set=typeof(AlienCreature).GetMethod("SetState",BindingFlags.NonPublic|BindingFlags.Instance);
   if(frost){set.Invoke(actor,new object[]{CreatureState.Volley});Check("Committed volley cannot be lured",!actor.CanBeLured);yield return null;set.Invoke(actor,new object[]{CreatureState.Orbit});yield return null;}else{set.Invoke(actor,new object[]{CreatureState.Charge});Check("Committed charge cannot be lured",!actor.CanBeLured);yield return null;actor.Agent.Warp(actor.transform.position+Vector3.forward*2);yield return null;}
   Check("Variant committed attack creates prewarned hazard",variant.HazardsCreated>0);var hazard=FindFirstObjectByType<FrontierHazard>();if(hazard){Check("Hazard starts with warning",!hazard.Armed);float age=hazard.Age;p.SetPaused(true);yield return new WaitForSecondsRealtime(.2f);Check("Hazard warning freezes on pause",Mathf.Abs(hazard.Age-age)<.01f);p.SetPaused(false);Destroy(hazard.gameObject);}
   p.arena.RestoreHealth(100);Check("Variant defeated through vitality system",actor.GetComponent<CreatureVitality>().TakeDamage(1000,actor.transform.position));Check("Variant field record learned",c.State.fieldRecords.Contains(frost?"frost":"magnetic"));int count=c.FrontierCount("variant");Check("Dead variant cannot reward twice",!actor.GetComponent<CreatureVitality>().TakeDamage(1000,actor.transform.position)&&c.FrontierCount("variant")==count);
  }
  IEnumerator GadgetCheck(){var p=c.Explorer;var region=c.RegionView;Freeze();Approach("survey");p.arena.RestoreHealth(100);var gadgets=p.GetComponent<FrontierGadgets>();Check("Tactical device controller exists",gadgets);var forward=p.transform.forward;forward.y=0;var point=p.transform.position+forward.normalized*4;if(NavMesh.SamplePosition(point,out var nav,4,NavMesh.AllAreas))point=nav.position;
   c.State.bag.Add(ItemId.BlastCore,4);c.State.bag.Add(ItemId.SoundDecoy,4);c.State.blastCooldown=0;c.State.decoyCooldown=0;int cores=c.State.bag.Count(ItemId.BlastCore);Check("Blast consumes one only after valid throw",gadgets.Deploy(false,point)&&c.State.bag.Count(ItemId.BlastCore)==cores-1);Check("Cooldown prevents repeat and conserves items",!gadgets.Deploy(false,point)&&c.State.bag.Count(ItemId.BlastCore)==cores-1);float timer=gadgets.BlastCooldown;p.SetPaused(true);yield return new WaitForSecondsRealtime(.2f);Check("Gadget flight and cooldown freeze",Mathf.Abs(gadgets.BlastCooldown-timer)<.01f);p.SetPaused(false);c.Save("frontier-gadget");var loaded=c.Store.Load("frontier-gadget");Check("Gadget cooldown roundtrip",loaded!=null&&loaded.blastCooldown>7);
   yield return new WaitForSeconds(2.2f);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.SetParent(p.arena.transform);wall.transform.position=(p.transform.position+point)*.5f+Vector3.up;wall.transform.localScale=new Vector3(3,4,.8f);Physics.SyncTransforms();int decoys=c.State.bag.Count(ItemId.SoundDecoy);Check("Cover prevents deployment through wall",!gadgets.Deploy(true,point)&&c.State.bag.Count(ItemId.SoundDecoy)==decoys);Destroy(wall);yield return null;Check("Sound lure consumes exactly one",gadgets.Deploy(true,point)&&c.State.bag.Count(ItemId.SoundDecoy)==decoys-1);yield return new WaitForSeconds(.6f);var lure=FindFirstObjectByType<FrontierDecoy>();Check("Lure becomes an independent world object",lure);if(lure){float remaining=lure.Remaining;p.SetPaused(true);yield return new WaitForSecondsRealtime(.2f);Check("Lure duration freezes on pause",Mathf.Abs(lure.Remaining-remaining)<.01f);p.SetPaused(false);}
   foreach(var actor in p.arena.creatures)if(actor.GetComponent<EliteCreature>())Check("Elite ignores lure",!FrontierDecoy.Find(actor,out _));yield return new WaitForSeconds(4.3f);Check("Lure expires without accumulating objects",!FindFirstObjectByType<FrontierDecoy>());
   var ordinary=new List<AlienCreature>();foreach(var actor in p.arena.creatures)if(actor.kind==CreatureKind.RiftMauler&&!actor.GetComponent<EliteCreature>()&&!actor.GetComponent<FrontierCreatureTrait>()&&!actor.GetComponent<CreatureVitality>().Dead)ordinary.Add(actor);
   if(ordinary.Count>=2){var visible=ordinary[0];var hidden=ordinary[1];NavMesh.SamplePosition(point+Vector3.right*1.7f,out var clearSpot,2,NavMesh.AllAreas);NavMesh.SamplePosition(point+Vector3.left*1.7f,out var hiddenSpot,2,NavMesh.AllAreas);visible.Agent.Warp(clearSpot.position);hidden.Agent.Warp(hiddenSpot.position);var cover=GameObject.CreatePrimitive(PrimitiveType.Cube);cover.transform.SetParent(p.arena.transform);cover.transform.position=(point+hidden.transform.position)*.5f+Vector3.up*1.4f;cover.transform.localScale=new Vector3(.18f,3,1.5f);Physics.SyncTransforms();int hp=visible.GetComponent<CreatureVitality>().Health,protectedHp=hidden.GetComponent<CreatureVitality>().Health;
    var g=new GameObject("QA blast cover trial");g.transform.SetParent(p.arena.transform);g.AddComponent<FrontierHazard>().Configure(p.arena,null,point,4,.8f,.3f,80,true,false);yield return new WaitForSeconds(1.2f);Check("Blast damages visible ordinary creature",visible.GetComponent<CreatureVitality>().Health==hp-80);Check("Blast cannot penetrate solid cover",hidden.GetComponent<CreatureVitality>().Health==protectedHp);Destroy(cover);
   }else Check("Blast trial has two ordinary targets",false);
  }
  IEnumerator Run(){var catalog=FrontierCatalog.Current;Check("Independent frontier catalog",catalog&&catalog.projects.Length==4&&catalog.commissions.Length==6&&catalog.landmarks.Length==5&&catalog.ruins.Length==3&&catalog.recipes.Length==3&&catalog.species.Length==7);Check("New items append stable IDs",(int)ItemId.MachineParts==14&&(int)ItemId.BlastCore==15&&(int)ItemId.SoundDecoy==16);
   var store=new CampaignStore(Path.Combine(Application.persistentDataPath,"FrontierMigrationQA"));var old=CampaignState.New();old.frontierCounters=null;old.frontierReceipts=null;old.fieldRecords=null;old.ruins=null;old.bag.Add(ItemId.IronOre,7);old.crates.Add(new SavedCrate{id="legacy-frontier",region=3});old.crates[0].items.Add(ItemId.Fuel,3);store.Save(old,"old-v2");var migrated=store.Load("old-v2");Check("Old v2 preserves inventory and death crate",migrated!=null&&migrated.bag.Count(ItemId.IronOre)==7&&migrated.crates[0].items.Count(ItemId.Fuel)==3&&migrated.frontierCounters!=null&&migrated.ruins!=null);
   CampaignRuntime.SeedFrontierHistory(migrated);Check("Finite legacy mining credited once",migrated.frontierCounters.Count==0);migrated.expansionProgress.Remove("frontier-initialized");for(int i=0;i<6;i++)migrated.minedNodes.Add("legacy-node-"+i);migrated.repairs.Add("0");CampaignRuntime.SeedFrontierHistory(migrated);Check("Old completed mining and forging remain claimable",migrated.frontierCounters.Find(x=>x.id=="mining").count==6&&migrated.frontierCounters.Find(x=>x.id=="forging").count==5);
   director.player.position=new Vector3(-10,director.surfaceY,0);Check("Construction locked until engineer",!c.BuildProject("carrier"));foreach(var key in new[]{"engineer-rescued","doctor-rescued","drone-rescued","greenhouse"})c.MarkExp(key);foreach(var item in new[]{ItemId.PurpleIngot,ItemId.CopperIngot,ItemId.IronIngot,ItemId.CobaltIngot,ItemId.MachineParts,ItemId.PurpleOre})c.State.warehouse.Add(item,40);c.State.warehouse.Add(ItemId.Fuel,10);
   foreach(var project in catalog.projects){Check("Camp project builds once "+project.id,c.BuildProject(project.id));Check("Camp project cannot duplicate "+project.id,!c.BuildProject(project.id));}Check("Carrier upgrades bag capacity",c.State.bag.capacity==24);var death=c.DropOnDeath(Vector3.zero);Check("Death preserves upgrade and contents",c.State.bag.capacity==24&&death.items.Count(ItemId.Ammo)==24);Check("Camp recovery returns inventory",c.RecoverCrate(death.id)&&c.State.bag.Count(ItemId.Ammo)==24);
   foreach(var recipe in catalog.recipes)Check("Recipe crafts "+recipe.id,c.CraftFrontier(recipe.id));var bag=c.State.bag;c.State.bag=new ItemContainer(16);c.State.bag.Add(ItemId.Ammo,16*99);int parts=Total(ItemId.MachineParts);Check("Full bag crafting rolls back cost",!c.CraftFrontier("blast")&&Total(ItemId.MachineParts)==parts);c.State.bag=bag;
   for(int i=0;i<6;i++){var node=director.ores[i].GetComponent<CampaignNode>();Check("Real mineral recovery advances commission "+i,c.CollectNode(node));Check("Duplicate node does not advance",!c.CollectNode(node));}Check("Mining commission capped at goal",c.FrontierCount("mining")==6);
   for(int i=0;i<5;i++){director.inventory.SelectedMetal=RepairResource.PurpleCopper;Check("Forge reserves real ore "+i,director.inventory.TryReserve(out var ore));Check("Forge resolves into commission "+i,director.inventory.Resolve(ore,true));Check("Forge receipt cannot resolve twice",!director.inventory.Resolve(ore,true));}Check("Forge commission counts success",c.FrontierCount("forging")==5);Check("Failed forge does not count",director.inventory.TryReserve(out var failed)&&director.inventory.Resolve(failed,false)&&c.FrontierCount("forging")==5);
   c.State.device=true;c.State.calibrated=true;for(int area=1;area<=5;area++){c.State.coordinates.Add(area);Check("Enter realm "+area,c.EnterRegion(area));yield return Wait(()=>c.Explorer&&!director.battle.IsTransitioning);Freeze();yield return null;Check("All new sites navigable "+area,c.RegionView.ExpansionSitesReachable());var site=c.RegionView.FrontierSitePosition("survey");yield return WalkTo(site,"survey "+area);yield return Survey(area);if(area>=2&&area<=4){yield return WalkTo(c.RegionView.FrontierSitePosition("ruin-control-1")+Vector3.back*2,"ruin branch "+area);yield return Ruin(area);}if(area==2||area==3)yield return Variant(area==3);if(area==2)yield return GadgetCheck();
    if(area==1){Approach("survey");foreach(var actor in c.Explorer.arena.creatures){Check("Existing creature kill records field knowledge",actor.GetComponent<CreatureVitality>().TakeDamage(1000,actor.transform.position));}}yield return WalkTo(c.Explorer.returnBeacon.position,"return "+area);yield return Leave();}
   director.player.position=new Vector3(-10,director.surfaceY,0);foreach(var commission in catalog.commissions){Check("Commission real progress complete "+commission.id,c.FrontierCount(commission.eventId)==commission.goal);Check("Commission rewards once "+commission.id,c.ClaimCommission(commission.id)&&!c.ClaimCommission(commission.id));}
   int overflowBefore=Total(ItemId.MachineParts);var oldBag=c.State.bag;var oldWarehouse=c.State.warehouse;c.State.bag=new ItemContainer(16);c.State.bag.Add(ItemId.Ammo,16*99);c.State.warehouse=new ItemContainer(48);c.State.warehouse.Add(ItemId.Ammo,48*99);int crateParts=0;foreach(var box in c.State.crates)crateParts+=box.items.Count(ItemId.MachineParts);c.State.expansionProgress.Remove("commission-miner");Check("Full containers retain commission in camp crate",c.ClaimCommission("miner"));int afterCrateParts=0;foreach(var box in c.State.crates)afterCrateParts+=box.items.Count(ItemId.MachineParts);Check("Overflow reward conserves exact quantity",afterCrateParts==crateParts+4&&!c.ClaimCommission("miner"));c.State.bag=oldBag;c.State.warehouse=oldWarehouse;
   c.State.bag.Sort();Check("Catalog sort keeps new tactical items",c.State.bag.Count(ItemId.BlastCore)>0&&c.State.bag.Count(ItemId.SoundDecoy)>0);c.Save("frontier-roundtrip");var loaded=c.Store.Load("frontier-roundtrip");Check("Full frontier save roundtrip",loaded!=null&&loaded.bag.capacity==24&&loaded.ruins.Count==3&&loaded.ruins.TrueForAll(r=>r.solved)&&loaded.fieldRecords.Contains("magnetic")&&loaded.expansionProgress.Contains("build-culture"));
   var invalid=CampaignState.New();invalid.frontierCounters.Add(new FrontierCounter{id="mining",count=99});store.Save(invalid,"invalid-counter");Check("Malformed progression rejected",store.Load("invalid-counter")==null);invalid=CampaignState.New();invalid.blastCooldown=float.PositiveInfinity;store.Save(invalid,"invalid-cooldown");Check("Malformed gadget timer rejected",store.Load("invalid-cooldown")==null);
   yield return Shot("rebuilt-camp",director.worldCamera);c.TrackObjective("surveys");Check("Finished survey tracking clears",string.IsNullOrEmpty(c.TrackedHint));c.TrackObjective("ruins");Check("Finished ruins tracking clears",string.IsNullOrEmpty(c.TrackedHint));
  }
 }
}
